# override para la unica evolucionada con tags distintos a la base
OVERRIDE = {
 P+"CAMISCILLA_UNFEELING_HEART_EVOLVED.description":
   "[gold]Invoca[/gold] un [gold]Juguete Chapucero[/gold] y una [gold]Marioneta Defectuosa[/gold]. [gold]Evolucionar[/gold]: todos los seguidores de tu mano con coste base de 2 o más.\n[purple]Superevolucionar[/purple]: Inflige 5X de daño a TODOS los enemigos, donde X es el número de seguidores de tu mano con coste base de 2 o más.",
}

def basekey(k):
    cid,fld=k.rsplit(".",1)
    cid=cid.replace("_SUPER_EVOLVED","").replace("_EVOLVED","")
    return cid+"."+fld

esp={}; missing=[]
for k in eng:
    if k in OVERRIDE: esp[k]=OVERRIDE[k]; continue
    bk=basekey(k)
    if bk in T: esp[k]=T[bk]
    else: missing.append(k)
if missing:
    print("FALTAN traducciones base:",len(missing))
    for k in sorted(set(basekey(x) for x in missing)): print("  ",k)
else:
    json.dump(esp, open(f"{OUT}/cards.json","w",encoding="utf-8"), ensure_ascii=False, indent=2)
    # validacion
    TAGS=("[gold]","[/gold]","[blue]","[/blue]","[purple]","[/purple]","[green]","[/green]")
    ok=True
    for k in eng:
        ev,sv=eng[k],esp[k]
        for t in TAGS:
            if ev.count(t)!=sv.count(t): ok=False; print(f"{k}: tag {t} {ev.count(t)}!={sv.count(t)}")
        if ev.count("{")!=sv.count("{") or ev.count("}")!=sv.count("}"):
            ok=False; print(f"{k}: llaves {ev.count('{')}/{ev.count('}')} vs {sv.count('{')}/{sv.count('}')}")
        et=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\(\))?\}',ev))
        st=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\(\))?\}',sv))
        if et!=st: ok=False; print(f"{k}: tokens {et} != {st}")
        if ev.count("\n")!=sv.count("\n"): ok=False; print(f"{k}: saltos {ev.count(chr(10))} != {sv.count(chr(10))}")
    print("CARDS VALIDACION OK" if ok else "REVISAR ^")
